"""Original lupus questions: recognition and organ assessment."""
from qbank_authoring import question,ref
rows=[]
C=ref('EULAR/ACR 2019 SLE classification criteria','https://doi.org/10.1002/art.40930')
S=ref('ACR 2025 SLE treatment guideline','https://doi.org/10.1002/acr.25690')
E=ref('EULAR SLE management: 2023 update','https://doi.org/10.1136/ard-2023-224762')
N=ref('ACR 2024 lupus nephritis guideline, published 2025','https://doi.org/10.1002/acr.25528')
K=ref('KDIGO 2024 lupus nephritis guideline','https://kdigo.org/guidelines/lupus-nephritis/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A 25-year-old woman has photosensitive facial rash, painless oral ulcers, inflammatory small-joint symptoms, leukopenia and proteinuria. Which diagnosis best unifies these findings?', 'Systemic lupus erythematosus',[
 ('Rheumatoid arthritis','RA can explain synovitis but does not as readily unify this mucocutaneous, hematological and renal pattern.'),('Systemic sclerosis','Raynaud phenomenon, sclerodactyly and its characteristic vascular/fibrosing manifestations would be stronger clues.'),('Adult-onset Still disease','Quotidian fever, neutrophilic leukocytosis and a compatible evanescent rash would be more typical.')],
 'Recognize multisystem immune disease','**The combination of mucocutaneous, articular, hematological and renal features strongly suggests SLE.**',['No isolated symptom or antibody establishes the diagnosis.','Infection, drug effects and other autoimmune disorders must be considered.'], '**Assess potentially organ-threatening disease at presentation.**',['Quantify proteinuria, examine urine sediment and measure kidney function.','Use ANA and disease-associated antibodies to support the clinical assessment.'],[['Mucocutaneous/articular','Common SLE domains'],['Cytopenia','May be immune, drug-related or infectious'],['Proteinuria','Requires renal evaluation']],[C,N],style='clinical_scenario')

q('What is the obligatory entry criterion for the 2019 EULAR/ACR SLE classification system?', 'ANA positivity at least once at a titer of at least 1:80 on HEp-2 cells or an equivalent test',[
 ('Anti-dsDNA positivity in every patient','This contributes a weighted immunological criterion but is not the obligatory entry test.'),('Biopsy-proven nephritis in every patient','Renal involvement is not required for all classified SLE.'),('Low C3 and low C4 on two occasions','Complement abnormalities contribute points but are not the entry requirement.')],
 'Classification criteria are not identical to diagnosis','**A qualifying ANA result is the entry requirement for this classification framework.**',['Weighted clinical and immunological criteria are then evaluated.','Clinical diagnosis still requires judgment, including in uncommon cases outside the classification framework.'], '**Do not diagnose lupus from ANA positivity alone.**',['The score requires an eligible pattern and at least one clinical criterion.','Only findings without a more likely explanation should be counted.'],[['ANA','Entry criterion'],['Clinical/immunological domains','Weighted items'],['Clinical diagnosis','Requires contextual judgment']],[C])

q('After meeting the ANA entry criterion, which scoring rule applies to the 2019 EULAR/ACR SLE classification criteria?', 'At least 10 points with at least one clinical criterion, counting only the highest item within each domain',[
 ('At least 6 points with every item in a domain added together','Six is the familiar RA threshold, not the SLE threshold; same-domain items are not all added.'),('Four unweighted items occurring simultaneously','This does not describe the 2019 weighted framework.'),('A positive ANA and any one additional antibody regardless of clinical features','A clinical criterion and sufficient weighted score are required.')],
 'Apply domain rules rather than double-counting related findings','**The classification threshold is at least ten points after the ANA entry criterion.**',['Only the highest-weighted item in a domain contributes.','Features need not all occur simultaneously, but another more likely explanation precludes counting a feature.'], '**Use the framework as a research classification aid.**',['A qualifying score is not permission to ignore infection or another mimic.','Failure to meet a classification threshold does not alone settle every clinical diagnostic question.'],[['Threshold','At least 10'],['Within a domain','Highest item only'],['Clinical evidence','At least one clinical criterion']],[C])

q('Which antibody is highly specific for SLE but is not sufficiently sensitive to exclude SLE when absent?', 'Anti-Sm',[
 ('Anti-histone','This is associated with drug-induced lupus but is not comparably specific for idiopathic SLE.'),('Anti-centromere','This is associated more strongly with limited cutaneous systemic sclerosis.'),('Anti-CCP','This is associated more strongly with rheumatoid arthritis.')],
 'Separate specificity from sensitivity','**Anti-Sm is a disease-specific supporting antibody in an appropriate clinical context.**',['Many patients with SLE do not have it.','It is not a reliable substitute for clinical activity or renal response assessment.'], '**Interpret an antibody panel according to the suspected disease.**',['Use urine, blood counts, complement and other tests to assess the active organ pattern.','An antibody result should not override a clearly better alternative diagnosis.'],[['Anti-Sm','Specific SLE association'],['Anti-centromere','Systemic sclerosis association'],['Anti-CCP','RA association']],[C])

q('A patient with known SLE develops increasing proteinuria, hematuria and RBC casts, with rising anti-dsDNA and falling complement. What is the most important next disease-directed assessment?', 'Evaluate active lupus nephritis and arrange kidney biopsy when appropriate',[
 ('Diagnose a flare solely from anti-dsDNA and omit urine assessment','Serology supports probability but does not define renal pathology or replace organ assessment.'),('Attribute the findings to uncomplicated cystitis without further evaluation','RBC casts and proteinuria point to a glomerular process requiring assessment.'),('Assume chronic scarring solely because creatinine was previously normal','Normal prior function does not exclude new active nephritis.')],
 'Use serology with objective renal findings','**Active sediment and changing protein excretion require evaluation for renal inflammation.**',['Biopsy distinguishes class, activity, chronicity and alternative lesions.','Serological changes alone are insufficient to determine the complete renal treatment strategy.'], '**Quantify proteinuria and assess kidney function and blood pressure.**',['Exclude infection and other glomerular causes when relevant.','Coordinate timely nephrology-rheumatology care.'],[['Anti-dsDNA/complement','Support activity assessment'],['RBC casts/proteinuria','Objective renal concern'],['Biopsy','Defines pathology when indicated']],[N,K],style='clinical_scenario')

q('A patient with SLE has a positive direct antiglobulin test but normal hemoglobin and no biochemical hemolysis. Which interpretation is correct?', 'A positive DAT alone does not establish active autoimmune hemolytic anemia',[
 ('Active immune hemolysis is established regardless of hemoglobin and hemolysis markers','Evidence of red-cell destruction and the clinical context are needed.'),('The result excludes immune-mediated red-cell disease in the future','A current isolated result does not predict that hemolysis can never develop.'),('The result proves thrombotic thrombocytopenic purpura','TTP is a microangiopathic syndrome and is not diagnosed from DAT positivity.')],
 'Document hemolysis before labeling hemolytic anemia','**DAT detects red-cell-bound immune material; it is not by itself proof of clinically active hemolysis.**',['Look for falling hemoglobin, reticulocytosis, indirect bilirubin/LDH elevation and reduced haptoglobin.','Blood film findings and alternative causes of anemia are important.'], '**Treat the clinical syndrome rather than the test alone.**',['Consider bleeding, iron deficiency, kidney disease and medication effects.','Microangiopathic hemolysis has a different evaluation pathway.'],[['DAT','Supports an immune mechanism'],['Hemolysis markers','Evidence of red-cell destruction'],['Anemia alone','Has many possible causes']],[C,S],style='clinical_scenario')

q('A woman with SLE has reducible ulnar deviation and MCP subluxation, with little erosive change. Which arthropathy is most characteristic?', 'Jaccoud arthropathy',[
 ('Classic erosive RA','Fixed deformity with marginal erosions is more characteristic, although true RA-SLE overlap can occur.'),('Arthritis mutilans','This usually involves marked destructive osteolysis rather than a mainly reducible deformity.'),('Hemochromatosis arthropathy','MCP hook osteophytes and iron-overload context are the more characteristic clues.')],
 'Deformity need not imply the RA erosion pattern','**Jaccoud arthropathy reflects deforming periarticular and ligamentous disease, classically with reducibility.**',['Traditional descriptions emphasize nonerosive disease, but sensitive imaging can identify lesions in some patients.','Persistent erosive synovitis raises the possibility of an overlap phenotype.'], '**Assess inflammation, structural change and function separately.**',['Provide hand therapy and joint protection as appropriate.','Select systemic treatment according to current inflammatory disease, not deformity alone.'],[['Jaccoud','Often reducible deformity'],['RA','Typically erosive synovitis'],['Function','May need rehabilitation despite low inflammation']],[S],style='clinical_scenario')

q('An SLE patient develops fever, focal lobar consolidation and hypoxemia while immunosuppressed. What is the priority before assuming a pulmonary lupus flare?', 'Evaluate and promptly treat possible infection while assessing other causes',[
 ('Escalate immunosuppression solely because complement is low','Low complement does not exclude a serious concurrent infection.'),('Exclude bacterial infection because lupus itself can cause fever','Infection is a major cause of morbidity during immunosuppression.'),('Diagnose diffuse alveolar hemorrhage from fever alone','Hemorrhage requires its own clinical, laboratory and imaging assessment.')],
 'Infection and flare can coexist','**Fever and lung infiltrates in an immunosuppressed patient demand an infection assessment.**',['The radiographic pattern, cultures, exposures and severity guide initial management.','Serology cannot reliably rule out infection in a patient with active lupus.'], '**Do not delay time-sensitive infection treatment in a sick patient.**',['Consider pulmonary embolism, hemorrhage and drug toxicity as the presentation warrants.','Adjust immune therapy with attention to both immediate risks.'],[['Focal consolidation','Infection is a major concern'],['Low complement','Does not exclude infection'],['Severe hypoxemia','Urgent physiological support']],[S,E],style='clinical_scenario')

q('An SLE patient has rapidly worsening hypoxemia, bilateral alveolar infiltrates and falling hemoglobin. Hemoptysis is absent. Which complication must be considered?', 'Diffuse alveolar hemorrhage',[
 ('Uncomplicated pleuritis','Pleuritis does not adequately explain a rapid hemoglobin fall with diffuse alveolar disease.'),('Stable interstitial lung fibrosis','This does not usually cause this abrupt anemia-plus-alveolar-infiltrate presentation.'),('Pulmonary arterial hypertension alone','This is not the best explanation for the acute alveolar and hematological pattern.')],
 'Absence of hemoptysis does not exclude lung hemorrhage','**Diffuse alveolar hemorrhage can present without visible hemoptysis.**',['Sequentially more hemorrhagic lavage can support the diagnosis when bronchoscopy is safe and appropriate.','Infection, edema and other causes of diffuse infiltrates must also be investigated.'], '**Treat this as a critical organ-threatening syndrome.**',['Provide oxygenation/ventilatory support and urgent specialist-directed treatment.','Review platelet count, coagulation, renal involvement and concurrent infection.'],[['Falling hemoglobin','Raises hemorrhage concern'],['Bilateral alveolar infiltrates','Nonspecific but compatible'],['No hemoptysis','Does not rule out DAH']],[S,E],style='clinical_scenario')

q('A patient with SLE has new psychosis and confusion after a large glucocorticoid dose increase. Which approach is best?', 'Assess steroid effects, infection, metabolic causes and other mimics before attributing the syndrome to inflammatory neuropsychiatric lupus',[
 ('Diagnose inflammatory CNS lupus automatically because ANA is positive','ANA does not establish the cause of a new neuropsychiatric syndrome.'),('Diagnose APS-related cerebral thrombosis without neurological examination or imaging','Vascular causes need objective assessment.'),('Increase glucocorticoids in every case without reviewing their timing','Steroid-associated psychiatric effects are an important differential.')],
 'Neuropsychiatric attribution requires a differential diagnosis','**SLE does not make every cognitive or psychiatric presentation inflammatory lupus.**',['Medication effects, infection, vascular events and metabolic abnormalities may be more likely.','Focal signs or seizures can require urgent neurological imaging and other testing.'], '**Separate inflammatory, thrombotic and non-SLE causes because treatment differs.**',['Assess safety, mental status and organ function promptly.','Use targeted CSF studies when indicated and safe, rather than an indiscriminate panel alone.'],[['Inflammatory syndrome','May need immunosuppression'],['Thrombotic syndrome','Requires vascular assessment/treatment'],['Steroid/metabolic/infectious cause','Treat the alternative mechanism']],[S,E],style='clinical_scenario')

q('A patient taking procainamide develops arthralgia, fever, pleuritic pain and anti-histone antibodies, without major renal or CNS disease. Which diagnosis is most likely?', 'Drug-induced lupus',[
 ('Antiphospholipid syndrome','This requires a compatible thrombotic/obstetric or related phenotype, not just these inflammatory symptoms.'),('Mixed connective tissue disease','High anti-U1 RNP with a compatible overlap phenotype is a more typical setting.'),('Systemic sclerosis','The vascular and fibrosing phenotype is not present.')],
 'Link the syndrome to an implicated exposure','**Procainamide is a classic cause of drug-induced lupus.**',['Anti-histone antibodies support the context but are not uniquely diagnostic.','Different culprit drugs can produce different phenotypes; hydralazine may also cause severe ANCA-associated disease.'], '**Review and stop the implicated medication when appropriate.**',['Most uncomplicated symptoms improve after withdrawal, although antibodies can persist.','Investigate major organ involvement rather than assume every drug-associated syndrome is mild.'],[['Classic drug-induced lupus','Arthralgia/serositis often prominent'],['Anti-histone','Supportive, not exclusive'],['Hydralazine','Can also produce vasculitic renal disease']],[ref('DermNet clinical reference: drug-induced lupus','https://dermnetnz.org/topics/drug-induced-lupus-erythematosus')],style='clinical_scenario')

q('Which maternal antibody is most directly associated with neonatal lupus and congenital atrioventricular block?', 'Anti-Ro/SSA',[
 ('Anti-centromere','This is associated with a different maternal autoimmune phenotype and is not the principal neonatal lupus antibody.'),('Anti-CCP','This is an RA-associated antibody rather than the principal congenital block association.'),('Anti-Jo-1','This supports an antisynthetase phenotype, not the characteristic neonatal lupus association.')],
 'Maternal antibody can affect the fetus without active maternal lupus','**Anti-Ro/SSA, often with anti-La/SSB, is associated with neonatal lupus.**',['The mother can be minimally symptomatic or have another autoimmune diagnosis.','Cutaneous manifestations may resolve as maternal antibodies clear, while established complete heart block is often permanent.'], '**Plan pregnancy counseling and appropriate fetal surveillance with specialists.**',['Risk is higher after a previously affected child.','Medication and surveillance recommendations should follow current reproductive guidance.'],[['Anti-Ro/SSA','Key neonatal lupus association'],['Maternal symptoms','Can be absent or mild'],['Established complete block','Often permanent']],[ref('EULAR reproduction/pregnancy recommendations: 2024 update','https://pubmed.ncbi.nlm.nih.gov/40287311/')])

if __name__=='__main__':print(f'Lupus diagnosis draft: {len(rows)} questions')
